// Parses docs/fire-drill.md (committed, regenerated by `npm run fire-drill` / scripts/fire-drill.ts
// — A's territory) rather than importing that script's functions directly: scripts/fire-drill.ts
// isn't an npm workspace package (next.config.ts's transpilePackages only covers @ringfence/engine),
// so a cross-package relative import wouldn't be transpiled by Next. Reading its committed markdown
// output keeps this read-only with respect to A's script and reuses the exact numbers it produced.
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export type Gate = "no gate" | "per-request gate" | "Ringfence";
export const GATES: Gate[] = ["no gate", "per-request gate", "Ringfence"];

export interface SweepRow {
  label: string;
  gate: Gate;
  leakedPer1000Usd: number;
  /** Honest members held per run of 1,000 test payouts (averaged, so it can be fractional). */
  honestHeld: number;
  honestHeldPct: number;
  precisionPct: number;
  recallPct: number;
}

export interface FireDrillData {
  ringShareSweep: SweepRow[];
  evasionSweep: SweepRow[];
}

// apps/console/lib/fire-drill-data.ts -> apps/console/lib -> apps/console -> apps -> repo root
const REPO_ROOT = path.resolve(fileURLToPath(import.meta.url), "..", "..", "..", "..");
const FIRE_DRILL_MD_PATH = path.join(REPO_ROOT, "docs", "fire-drill.md");

const ROW_RE = /^\|\s*(.+?)\s*\|\s*(no gate|per-request gate|Ringfence)\s*\|\s*\$(-?[\d.]+)\s*\|\s*(-?[\d.]+)\s*\((-?[\d.]+)%\)\s*\|\s*(-?[\d.]+)%\s*\|\s*(-?[\d.]+)%\s*\|$/;

export function parseFireDrillMarkdown(markdown: string): FireDrillData {
  const ringShareSweep: SweepRow[] = [];
  const evasionSweep: SweepRow[] = [];
  let section: "ring-share" | "evasion" | undefined;

  for (const line of markdown.split("\n")) {
    if (line.startsWith("### Sweep: ring share")) {
      section = "ring-share";
      continue;
    }
    if (line.startsWith("### Sweep: ring accounts that fake activity")) {
      section = "evasion";
      continue;
    }
    const match = ROW_RE.exec(line.trim());
    if (!match || !section) continue;
    const [, label, gate, leaked, honestHeld, honestHeldPct, precisionPct, recallPct] = match;
    const row: SweepRow = {
      label: label as string,
      gate: gate as Gate,
      leakedPer1000Usd: Number(leaked),
      honestHeld: Number(honestHeld),
      honestHeldPct: Number(honestHeldPct),
      precisionPct: Number(precisionPct),
      recallPct: Number(recallPct),
    };
    (section === "ring-share" ? ringShareSweep : evasionSweep).push(row);
  }

  return { ringShareSweep, evasionSweep };
}

export function loadFireDrillData(): FireDrillData {
  return parseFireDrillMarkdown(readFileSync(FIRE_DRILL_MD_PATH, "utf-8"));
}

/** The ring-share sweep's own 5% rows are the headline run: the same `drill({ ringShare: 0.05 })` the report's headline paragraph quotes. */
export function headlineRows(data: FireDrillData): SweepRow[] {
  return data.ringShareSweep.filter((r) => r.label === "5%");
}
